-- ============================================================
-- league_data_ucl.sql — 欧冠真实数据入库（由 scripts_cloudbase/build-ucl-db.py 生成）
-- 数据源：赛程/淘汰赛=腾讯体育（data/ucl.json）｜积分榜/射手榜=央视体育
-- 前置：db/schema.sql（season / zone 列）
-- 执行顺序：schema.sql → league_data.sql → league_data_nba.sql → league_data_cba.sql
--   → league_data_epl.sql → 本文件
--   （league_data.sql 里有一段 ucl 的旧数据，须被本文件覆盖）
-- 可重复执行：先清空 league_id=ucl / league=欧冠 的行，再插入
-- 规模：league_schedule 333 · league_standings 72 · league_players 55 · league_brackets 2 · matches 1
-- ============================================================

BEGIN;

-- ---------- 1. 联赛维度表（与真实数据的 desc / tabs 对齐）----------
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, sport = EXCLUDED.sport,
  emoji = EXCLUDED.emoji, description = EXCLUDED.description,
  tabs = EXCLUDED.tabs, updated_at = EXCLUDED.updated_at;

-- ---------- 2. 清空欧冠旧数据（含 league_data.sql 灌的 ucl 段）----------
DELETE FROM public.league_schedule WHERE league_id = 'ucl';
DELETE FROM public.league_standings WHERE league_id = 'ucl';
DELETE FROM public.league_players WHERE league_id = 'ucl';
DELETE FROM public.league_brackets WHERE league_id = 'ucl';
DELETE FROM public.matches WHERE league = '欧冠';

-- ---------- 3. league_schedule（两个赛季正赛 333 场）----------

-- ---------- 4. league_standings（两个赛季各 36 队联赛阶段榜，无分区）----------

-- ---------- 5. league_players（26-27 射手榜 55 人，board=scorers）----------

-- ---------- 6. league_brackets（25-26 晋级图 + 淘汰赛对阵）----------

-- ---------- 7. matches（赛程比分页欧冠段 1 条）----------

COMMIT;

-- 收尾自检
SELECT 'league_schedule' t, count(*) FROM public.league_schedule WHERE league_id='ucl'
UNION ALL SELECT 'league_standings', count(*) FROM public.league_standings WHERE league_id='ucl'
UNION ALL SELECT 'league_players',   count(*) FROM public.league_players   WHERE league_id='ucl'
UNION ALL SELECT 'league_brackets',  count(*) FROM public.league_brackets  WHERE league_id='ucl'
UNION ALL SELECT 'matches(欧冠)',    count(*) FROM public.matches        WHERE league='欧冠';
SELECT season, count(*) FROM public.league_schedule WHERE league_id='ucl' GROUP BY season ORDER BY season;
SELECT season, count(*) FROM public.league_standings WHERE league_id='ucl' GROUP BY season ORDER BY season;
